  if (cells.length < 4) return [cells];
  const get = (c: TextCell) => c[axis];
  const centers = cluster(cells.map(get), tolerance);
  if (centers.length < 3) return [cells];

  const gaps: number[] = [];
  for (let i = 1; i < centers.length; i++) gaps.push(centers[i] - centers[i - 1]);
