export function shouldUseLlm(table: TableData, enabled: boolean): boolean {
  return enabled && !!getLlmConfig() && (table.confidence < LLM_CONFIDENCE_THRESHOLD || table.warnings.length > 0);
}

export async function enhanceWithLlm(
  table: TableData,
  page: PageData,
  config: LlmConfig
): Promise<TableData> {
  const prompt = [
    'You are a PDF table extraction assistant. Given the raw text cells with coordinates from one PDF page and a rule-based extraction result, output a corrected table.',
