import { createCanvas } from 'canvas';
import * as pdfjsLib from 'pdfjs-dist/legacy/build/pdf.mjs';
import type { PageData } from './parser';

const STANDARD_FONTS = path.join(process.cwd(), 'node_modules', 'pdfjs-dist', 'standard_fonts');

export function createPdfDocument(buffer: Buffer) {
  return pdfjsLib.getDocument({
    data: new Uint8Array(buffer),
    useSystemFonts: true,
    isEvalSupported: false,
    standardFontDataUrl: `${STANDARD_FONTS}${path.sep}`,
  }).promise;
}

export async function renderPageToPngBuffer(
  doc: Awaited<ReturnType<typeof createPdfDocument>>,
  pageNumber: number,
  scale = 1.5
): Promise<Buffer> {
  const page = await doc.getPage(pageNumber);
  const viewport = page.getViewport({ scale });
  const canvas = createCanvas(Math.floor(viewport.width), Math.floor(viewport.height));
  const ctx = canvas.getContext('2d');
  await page.render({ canvasContext: ctx as unknown as CanvasRenderingContext2D, viewport }).promise;
  return canvas.toBuffer('image/png');
}

export function pageDataFromDoc(
  doc: Awaited<ReturnType<typeof createPdfDocument>>,
  maxPages: number
): Promise<import('./parser').PageData[]> {
  return import('./parser').then(({ pageDataFromPdfDocument }) => pageDataFromPdfDocument(doc, maxPages));
}
","explanation":"创建 PDF 页面渲染模块，配置标准字体路径。"}}]}

