- 计算所有数据行的最大列数 N
- 表头多于 N → 截断（去掉尾部占位列），少于 N → 补空
- 所有行统一到 N 列
- 清理 `^{±}^{0.00}` → `^{±0.00}` 这类冗余

在 map 之前应用。"},{"type":"tool-call","toolCallId":"chatcmpl-tool-9c20a677cf4aa50a","toolName":"replace_in_file","args":{"filePath":"f:\ai-tool-projects\pdf-table-extractor\lib\llm\fallback.ts","old_str":"export async function extractPageWithLlm(","new_str":"function cleanCellText(text: string): string {
  // LLM sometimes emits chained superscripts like 98.87^{±}^{0.00}; fold them.
  return text.replace(/\^\{([^{}]*)\}\^\{([^{}]*)\}/g, '^{$1$2}');
}

function normalizeTable(t: z.infer<typeof LLM_TABLE>) {
  const headers = t.headers.map(cleanCellText);
  const rows = t.rows.map((row) => row.map(cleanCellText));
  const dataCols = Math.max(0, ...rows.map((r) => r.length));
  const headerCols = headers.length;
  const colCount = Math.max(dataCols, headerCols > 0 && dataCols === 0 ? headerCols : dataCols);

  let normalizedHeaders = headers;
  if (colCount > 0) {
    normalizedHeaders = headers.slice(0, colCount);
    while (normalizedHeaders.length < colCount) normalizedHeaders.push('');
  }
  const normalizedRows = rows.map((row) => {
    const r = row.slice(0, colCount);
    while (r.length < colCount) r.push('');
    return r;
  });

  return { ...t, headers: normalizedHeaders, rows: normalizedRows, columnCount: colCount };
}

