   253: * covers, leaving all other cells (e.g. row-spanning Method/Latency) intact.
   254: * Returns null when the layout cannot be matched confidently.
   255: */
   256:function correctParentHeaderFromCoords(
   257:  page: PageData,
   258:  headerRows: string[][],
   259:  firstDataRow: string[],
   260:  colCount: number
   261:): string[][] | null {
   262:  if (headerRows.length < 2 || colCount < 2) return null;
   263:
   264:  const matchText = firstDataRow.find((v) => v.trim())?.trim() ?? '';
   265:  if (!matchText) return null;
   266:  const anchor = page.cells.find((c) => c.text.trim() === matchText);
   267:  if (!anchor) return null;
   268:  const dataY = anchor.y;
   269:
   270:  const sorted = [...page.cells].filter((c) => c.text.trim()).sort((a, b) => a.y - b.y);
   271:  const visualRows: (typeof page.cells)[] = [];
   272:  for (const cell of sorted) {
   273:    const row = visualRows.find((r) => Math.abs(r[0].y - cell.y) <= 4);
   274:    if (row) row.push(cell); else visualRows.push([cell]);
   275:  }
   276:  const dataRow = visualRows.find((r) => Math.abs(r[0].y - dataY) <= 4);
   277:  if (!dataRow) return null;
   278:
   279:  // Merge text fragments sharing a column (e.g. "×" + "1.0000") by x-origin
   280:  // proximity. Distinct columns have their x origins far enough apart.
   281:  const dataCells = [...dataRow].sort((a, b) => a.x - b.x);
   282:  const groups: { left: number; right: number; lastX: number }[] = [];
   283:  for (const cell of dataCells) {
   284:    const last = groups[groups.length - 1];
   285:    if (last && cell.x - last.lastX <= 15) {
   286:      last.right = Math.max(last.right, cell.x + cell.width);
   287:      last.lastX = cell.x;
   288:    } else {
   289:      groups.push({ left: cell.x, right: cell.x + cell.width, lastX: cell.x });
   290:    }
   291:  }
   292:  if (groups.length !== colCount) return null;
   293:  const centers = groups.map((g) => (g.left + g.right) / 2);
   294:
   295:  // Parent header line = the topmost visual row within 70pt above the data row.
   296:  const headerVisual = visualRows.filter((r) => r[0].y < dataY - 4 && dataY - r[0].y < 70);
   297:  if (!headerVisual.length) return null;
   298:  const parentCells = [...headerVisual[0]].sort((a, b) => a.x - b.x);
