但这里有个问题：`Method`/`Latency` 在父行和子行都是文本，渲染时父行 `rowSpan=2`、子行被 `covered`。但父行的 `Diversity` 跨 2 列、而 `GenEval`/`DPG` 不跨列，这会让父行的单元格数和子行对不上。这是 HTML table 用 colSpan/rowSpan 的正常表现——浏览器会自动对齐。让我写脚本验证合并结构。"},{"type":"tool-call","toolCallId":"chatcmpl-tool-a14b98279ddf862d","toolName":"write_to_file","args":{"filePath":"f:\ai-tool-projects\pdf-table-extractor\scripts\verify-header-structure.mjs","content":"import fs from 'fs';
const BASE = 'http://127.0.0.1:3000';
const pdf = fs.readFileSync('tests/real-pdfs/003.pdf');
const form = new FormData();
form.append('file', new Blob([pdf], { type: 'application/pdf' }), '003.pdf');
const up = await (await fetch(`${BASE}/api/upload`, { method: 'POST', body: form })).json();
const ex = await (await fetch(`${BASE}/api/extract`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ key: up.key, fileName: up.fileName, enableLlm: true }),
})).json();
const t = ex.tables[0];
const lines = t.headerRows.map((hr) => hr.map((s) => (s ?? '').trim()));
const cols = t.columnCount;
const textAt = (ri, c) => lines[ri]?.[c] ?? '';
const covered = lines.map(() => Array.from({ length: cols }, () => false));
for (let ri = 1; ri < lines.length; ri++)
  for (let c = 0; c < cols; c++)
    if (textAt(ri, c) && textAt(ri, c) === textAt(ri - 1, c)) covered[ri][c] = true;
const rs = (ri, c) => {
  let s = 1;
  for (let r = ri + 1; r < lines.length && covered[r][c]; r++) s++;
  return s;
};
for (let ri = 0; ri < lines.length; ri++) {
  const cells = [];
  let c = 0;
  while (c < cols) {
    if (covered[ri][c]) { c++; continue; }
    const text = textAt(ri, c);
    const rowSpan = rs(ri, c);
    let colSpan = 1;
    while (c + colSpan < cols && !covered[ri][c + colSpan] &&
           textAt(ri, c + colSpan) === text && rs(ri, c + colSpan) === rowSpan && text) colSpan++;
    cells.push(`${text || '""'}[r${rowSpan}c${colSpan}]`);
    c += colSpan;
  }
