/**
 * Restore vertically-merged data cells (multirow). In PDFs the label of a
 * multirow cell is vertically centred, so the LLM places it on the middle
 * data row instead of the first. Using text coordinates we find each label's
 * y, split the data rows at the midpoints between consecutive labels, and
 * repeat each label across its group so the renderer's rowSpan merges it.
 */
function restoreMergedDataCells(
  page: PageData,
  rows: string[][],
  colCount: number
): string[][] | null {
  if (rows.length < 3 || colCount < 2) return null;

  // Locate data-row y positions from the first dense numeric column (col 1):
  // find a value from the first row that appears as a single page text item.
  const firstVals = rows[0].map((v) => v.trim()).filter(Boolean);
  const anchorText = firstVals.find((v) => /^[\d.,%+\-]+$/.test(v));
  if (!anchorText) return null;
  const anchors = page.cells.filter((c) => c.text.trim() === anchorText);
  if (!anchors.length) return null;

  // Try each anchor as the first data row; pick the one yielding `rows.length`
  // consecutive visual rows below it.
  const sorted = [...page.cells].filter((c) => c.text.trim()).sort((a, b) => a.y - b.y);
  const dataRowYsCandidates: number[][] = [];
  for (const anchor of anchors) {
    const startIdx = sorted.findIndex((c) => c === anchor);
    if (startIdx < 0) continue;
    const ys: number[] = [];
    for (let i = startIdx; i < sorted.length && ys.length < rows.length; i++) {
      const y = sorted[i].y;
      if (ys.length === 0 || y - ys[ys.length - 1] > 8) ys.push(y);
    }
    if (ys.length === rows.length) dataRowYsCandidates.push(ys);
  }
  if (!dataRowYsCandidates.length) return null;
  const dataYs = dataRowYsCandidates[0];

  // Collect non-empty labels for column 0 within the data-row y band.
  const bandLo = dataYs[0] - 6;
  const bandHi = dataYs[dataYs.length - 1] + 6;
  const colZeroX = page.cells
    .filter((c) => c.text.trim() && rows.some((r) => r[0]?.trim() === c.text.trim()))
    .map((c) => c.x);
  if (!colZeroX.length) return null;
  const labelX = Math.min(...colZeroX);

  const labels: { text: string; y: number }[] = [];
  for (const cell of page.cells) {
    const text = cell.text.trim();
    if (!text || cell.y < bandLo || cell.y > bandHi) continue;
    if (Math.abs(cell.x - labelX) > 30) continue;
    // Only page texts that match a value appearing in column 0 of the rows.
    if (!rows.some((r) => r[0]?.trim() === text)) continue;
    if (!labels.some((l) => l.text === text && Math.abs(l.y - cell.y) <= 8)) {
      labels.push({ text, y: cell.y });
    }
  }
  if (labels.length < 2) return null;
  labels.sort((a, b) => a.y - b.y);

  // Assign each data row to the nearest label (no midpoint needed: nearest
  // label by y works for groups whose label is vertically centred).
  const boundaries = labels.slice(1).map((l, i) => (labels[i].y + l.y) / 2);
  const restored = rows.map((row) => [...row]);
  for (let ri = 0; ri < dataYs.length; ri++) {
    let gi = 0;
    while (gi < boundaries.length && dataYs[ri] >= boundaries[gi]) gi++;
    if (restored[ri][0]?.trim()) continue; // keep an existing value if present
    restored[ri][0] = labels[gi].text;
  }
  return restored;
}

