    if (page.cells.length > 100) {
      const ys = page.cells.map((c) => c.y).sort((a, b) => a - b);
      const midY = ys[Math.floor(ys.length / 2)];
      const halves: PageData[] = [
        { ...page, cells: page.cells.filter((c) => c.y <= midY) },
