 */
function splitSideBySideTables(
  page: PageData,
  headerRows: string[][],
  rows: string[][],
  colCount: number
): { headerRows: string[][]; rows: string[][] }[] | null {
  if (rows.length < 2 || colCount < 4 || headerRows.length === 0) return null;
  // Detect prose header: first header text is long and far above the data row.
  const firstText = headerRows[0][0]?.trim() ?? '';
  if (firstText.length < 25 || !/\s/.test(firstText) || /\d/.test(firstText)) return null;
  const proseHit = page.cells.find((c) => c.text.trim() === firstText);
  if (!proseHit) return null;

