  const numeric = rows[0].find((v) => /\d/.test(v ?? ''))?.trim() ?? '';
  const anchor = page.cells.find((c) => c.text.trim() === numeric);
  if (!anchor || proseHit.y >= anchor.y) return null;
  const sorted = [...page.cells].filter((c) => c.text.trim()).sort((a, b) => a.y - b.y);
  const headerLine = sorted.filter((c) => c.y < anchor.y - 4 && anchor.y - c.y < 45 && c.y > proseHit.y);
  if (headerLine.length < 4) return null;
  const byX = [...headerLine].sort((a, b) => a.x - b.x);
  // Group header items by x gaps; a gap >30pt marks a separate sub-table.
  const groups: (typeof page.cells)[] = [];
  for (const c of byX) {
    const last = groups[groups.length - 1];
    if (last && c.x - last[last.length - 1].x > 30) groups.push([c]);
    else if (last) last.push(c);
    else groups.push([c]);
  }
  if (groups.length < 2) return null;
  const sizes = groups.map((g) => g.length);
  if (!sizes.every((s) => s === sizes[0])) return null;
  if (sizes[0] * groups.length !== colCount) return null;

  return groups.map((g) => {
    const header = g.map((c) => c.text.trim());
    return {
      headerRows: [header],
      rows: rows.map((row) => {
        // Each sub-table occupies a contiguous block of `size` columns.
        const gi = groups.indexOf(g);
        return row.slice(gi * sizes[0], (gi + 1) * sizes[0]);
      }),
    };
  });
